// Home (`home.tenshu.app`) — a Tenshu app on its own origin (ADR 0020), on the shared app
// preset (`@tenshu/app-kit`, web-app-suite.md F3): Vite + Vitest + Tailwind, the dev server's
// `fs.allow` and the served `manifest.webmanifest`. Generated by scripts/new-web-app.sh.
//
// ⚠ Imported by its file path, not `@tenshu/app-kit/vite`: Node loads this config and refuses to
// strip types from a `.ts` it resolved through `node_modules`.
import { tenshuAppConfig } from '../app-kit/src/vite.ts'

// ⚠ No `chunkSizeWarningLimit` override: this bundle must NOT contain the Kotlin runtime, so Vite's
// default 500 kB warning is the tripwire for a stray SDK value import.
export default tenshuAppConfig({
  // The apex registry entry (`web/apex/src/apps/registry/apps/home.ts`) names the same port.
  port: 5181,
  manifest: {
    id: 'home',
    name: 'Home',
    description: 'Your devices, automations and activity — view only, end-to-end encrypted.',
    // ⚠ Read only (web-app-suite.md §8 items 2 and 9): there is no write to declare.
    semanticPermissions: [
      {
        id: 'tenshu/home/read',
        humanDescription: 'View your devices, hub storage, automations and their activity',
        scope: ['/'],
      },
    ],
  },
})
